function collect(list, found = []) {
  for (const item of list) {
    if (Array.isArray(item)) {
      collect(item);
    } else {
      found.push(item);
    }
  }

  return found;
}

console.log(collect(["a", ["b", ["c"]], "d"]).join(""));
console.log(collect(["x", "y"]).join(""));
console.log(collect([["z"]]).length);
